// One invoice, one row — and every cell traceable back to the message.
const cfg = $('Set your sheet and policy').first().json;
// The sender and the subject come from the trigger item, not from the parse:
// Resolved and Simple hand MailMint the body, so it never sees the headers.
const mail = $('Watch the invoices mailbox').all();
const rows = [];

for (const item of $input.all()) {
  const inv = item.json;
  const conf = inv._confidence || {};
  const meta = inv._meta || {};
  const reasons = [];

  const scores = Object.values(conf)
    .map((f) => (f && typeof f.confidence === 'number' ? f.confidence : null))
    .filter((n) => n !== null);
  const lowest = scores.length ? Math.min(...scores) : null;

  // Number(null) is 0, and an invoice for nothing is not an invoice.
  const raw = inv.amount_due;
  const hasAmount = raw !== null && raw !== undefined && raw !== '';
  const amount = hasAmount ? Number(raw) : null;

  if (amount !== null && Number.isFinite(amount) && amount > cfg.review_above) {
    reasons.push(`${amount} is above the ${cfg.review_above} review threshold`);
  }
  if (inv.currency && cfg.expected_currency && inv.currency !== cfg.expected_currency) {
    reasons.push(`currency ${inv.currency} is not ${cfg.expected_currency}`);
  }

  let daysUntilDue = null;
  if (inv.due_date) {
    const due = new Date(inv.due_date);
    if (!Number.isNaN(due.valueOf())) {
      daysUntilDue = Math.round((due - new Date($now.toISO())) / 86400000);
      if (daysUntilDue < 0) reasons.push(`already overdue by ${Math.abs(daysUntilDue)} days`);
    }
  }

  // The evidence, collapsed into one cell you can read next to the value.
  const evidence = Object.entries(conf)
    .map(([name, f]) => `${name}=${f && f.confidence !== null ? f.confidence : '?'} \u00ab${(f && f.evidence) || ''}\u00bb`)
    .join(' | ');

  const src = (mail[item.pairedItem && item.pairedItem.item !== undefined ? item.pairedItem.item : 0] || {}).json || {};
  const sender = src.from && src.from.value && src.from.value[0] ? src.from.value[0].address : null;

  rows.push({ json: {
    status: reasons.length ? 'review' : 'ok',
    invoice_number: inv.invoice_number ?? null,
    amount_due: amount !== null && Number.isFinite(amount) ? amount : null,
    currency: inv.currency ?? null,
    due_date: inv.due_date ?? null,
    iban: inv.iban ?? null,
    days_until_due: daysUntilDue,
    lowest_confidence: lowest,
    evidence,
    reason: reasons.join('; '),
    from: meta.from_email ?? sender ?? null,
    subject: meta.subject || src.subject || null,
    received_at: meta.received_at ?? src.date ?? null,
    request_id: meta.request_id ?? null,
  }, pairedItem: item.pairedItem });
}

return rows;
